import{o as l,c as n,a6 as a,j as t,k as e,g as r,a as d}from"./chunks/framework.DMOj2-2K.js";const s={class:"brand-logos"},i=["src"],c={class:"on-dark"},u=["src"],h=["src"],g={class:"on-dark"},b=["src"],k=["src"],f=["src"],w=JSON.parse('{"title":"Brand & logo","description":"","frontmatter":{},"headers":[],"relativePath":"brand.md","filePath":"brand.md"}'),m={name:"brand.md"},B=Object.assign(m,{setup(p){return(v,o)=>(l(),n("div",null,[o[6]||(o[6]=a('<h1 id="brand-logo" tabindex="-1">Brand &amp; logo <a class="header-anchor" href="#brand-logo" aria-label="Permalink to &quot;Brand &amp; logo&quot;">​</a></h1><p>Cluub <em>clubs together</em> the frontend, the backend and AI. The logo says exactly that: a club (♣) made of <strong>three circles</strong>, one for each part, joined on a single stem.</p><h2 id="logo-files" tabindex="-1">Logo files <a class="header-anchor" href="#logo-files" aria-label="Permalink to &quot;Logo files&quot;">​</a></h2><p>All files are plain SVG in the repository&#39;s <code>docs/public/</code> folder and are served from this site.</p>',4)),t("div",s,[t("figure",null,[t("img",{src:e(r)("/logo-full.svg"),alt:"Cluub logo with wordmark, for light backgrounds"},null,8,i),o[0]||(o[0]=t("figcaption",null,[t("code",null,"/logo-full.svg"),d(" · light backgrounds")],-1))]),t("figure",c,[t("img",{src:e(r)("/logo-full-dark.svg"),alt:"Cluub logo with wordmark, for dark backgrounds"},null,8,u),o[1]||(o[1]=t("figcaption",null,[t("code",null,"/logo-full-dark.svg"),d(" · dark backgrounds")],-1))]),t("figure",null,[t("img",{src:e(r)("/logo.svg"),alt:"Cluub mark, for light backgrounds"},null,8,h),o[2]||(o[2]=t("figcaption",null,[t("code",null,"/logo.svg"),d(" · mark only")],-1))]),t("figure",g,[t("img",{src:e(r)("/logo-dark.svg"),alt:"Cluub mark, for dark backgrounds"},null,8,b),o[3]||(o[3]=t("figcaption",null,[t("code",null,"/logo-dark.svg"),d(" · mark on dark")],-1))]),t("figure",null,[t("img",{src:e(r)("/wordmark.svg"),alt:"Cluub wordmark"},null,8,k),o[4]||(o[4]=t("figcaption",null,[t("code",null,"/wordmark.svg"),d(" · wordmark only")],-1))]),t("figure",null,[t("img",{src:e(r)("/favicon.svg"),alt:"Cluub favicon"},null,8,f),o[5]||(o[5]=t("figcaption",null,[t("code",null,"/favicon.svg"),d(" · adapts to dark mode")],-1))])]),o[7]||(o[7]=a('<p>The wordmark is drawn with simple strokes (no font), so it looks identical everywhere and needs no font licence.</p><h2 id="colours" tabindex="-1">Colours <a class="header-anchor" href="#colours" aria-label="Permalink to &quot;Colours&quot;">​</a></h2><p>The three circles use the <strong>Okabe–Ito palette</strong>, a set of colours designed to stay distinguishable for people with colour-vision deficiency.</p><div class="brand-swatches"><div style="background:#0072B2;color:#fff;"><b>Blue #0072B2</b><br>Frontend · brand colour</div><div style="background:#E69F00;color:#1E293B;"><b>Orange #E69F00</b><br>Backend</div><div style="background:#009E73;color:#fff;"><b>Green #009E73</b><br>AI</div><div style="background:#1E293B;color:#fff;"><b>Ink #1E293B</b><br>Stem, wordmark, text</div><div style="background:#56B4E9;color:#0B1220;"><b>Sky #56B4E9</b><br>Brand colour on dark</div></div><table tabindex="0"><thead><tr><th>Token</th><th>Hex</th><th>Used for</th><th>Contrast</th></tr></thead><tbody><tr><td>Blue</td><td><code>#0072B2</code></td><td>Frontend circle, links and buttons on light backgrounds</td><td>5.2 : 1 on white (WCAG AA for text)</td></tr><tr><td>Orange</td><td><code>#E69F00</code></td><td>Backend circle</td><td>Decorative; not used for text</td></tr><tr><td>Green</td><td><code>#009E73</code></td><td>AI circle</td><td>Decorative; not used for text</td></tr><tr><td>Ink</td><td><code>#1E293B</code></td><td>Stem, wordmark, body text</td><td>14.6 : 1 on white</td></tr><tr><td>Sky</td><td><code>#56B4E9</code></td><td>Links and buttons on dark backgrounds</td><td>7.4 : 1 on <code>#1B1B1F</code></td></tr><tr><td>Light ink</td><td><code>#F1F5F9</code></td><td>Stem and wordmark on dark backgrounds</td><td>15.7 : 1 on <code>#1B1B1F</code></td></tr></tbody></table><h3 id="colour-blind-check" tabindex="-1">Colour-blind check <a class="header-anchor" href="#colour-blind-check" aria-label="Permalink to &quot;Colour-blind check&quot;">​</a></h3><p>The three circle colours were checked with the Machado (2009) colour-vision simulation, measuring how different each pair still looks (CIEDE2000 ΔE; above about 10 is clearly different):</p><table tabindex="0"><thead><tr><th>Vision</th><th>Blue / orange</th><th>Blue / green</th><th>Orange / green</th></tr></thead><tbody><tr><td>Typical</td><td>55.4</td><td>38.4</td><td>42.9</td></tr><tr><td>Protanopia (no red cones)</td><td>55.7</td><td>38.4</td><td>17.9</td></tr><tr><td>Deuteranopia (no green cones)</td><td>62.7</td><td>34.6</td><td>26.5</td></tr><tr><td>Tritanopia (no blue cones, rare)</td><td>51.4</td><td>12.4</td><td>55.5</td></tr></tbody></table><p>The mark never relies on colour alone: each circle has a fixed position (frontend left, backend right, AI on top) and a white ring separates it from its neighbours, so the shape reads the same in greyscale.</p><p>The same blue is the default <code>--primary</code> colour of every Cluub app, and the <a href="/cookbook/theming">default theme</a> uses <code>#56B4E9</code> in dark mode.</p><h2 id="usage" tabindex="-1">Usage <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Usage&quot;">​</a></h2><ul><li><strong>Do</strong> leave space around the logo at least as wide as one circle.</li><li><strong>Do</strong> use the dark variants on dark backgrounds.</li><li><strong>Don&#39;t</strong> recolour, rotate, stretch or add effects to the mark.</li><li><strong>Don&#39;t</strong> swap the circle colours: blue, orange and green always stand for frontend, backend and AI.</li><li>The name is written <strong>Cluub</strong> in text and <strong>cluub</strong> for the command, the package and the wordmark.</li></ul><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="/guide/introduction#why-the-name-cluub">Why the name Cluub</a></li><li><a href="/cookbook/theming">Custom theme and styling</a></li></ul>',14))]))}});export{w as __pageData,B as default};
